import XCTest
#if KITCHEN_UI
final class V8Journey:XCTestCase {
 var a:XCUIApplication!
 override func setUp(){continueAfterFailure=false;a=XCUIApplication();a.launchArguments=["-folio-reset","-AppleLanguages","(en)","-AppleLocale","en_US"];a.launch()}
 func t9(_ s:String)->XCUIElement{a.descendants(matching:.any).matching(NSPredicate(format:"label == %@",s)).firstMatch}
 func shot(_ n:String){let x=XCTAttachment(screenshot:XCUIScreen.main.screenshot());x.name=n;x.lifetime = .keepAlways;add(x)}
 func reveal(_ e:XCUIElement){for _ in 0..<8{if e.exists && e.isHittable{return};a.swipeUp()}}
 func openRecipe(){let card=a.buttons["recipe.cupcake"];reveal(card);XCTAssertTrue(card.waitForExistence(timeout:12));card.tap();XCTAssertTrue(a.staticTexts["recipe.title"].waitForExistence(timeout:5))}
 func testKitchenFlowAndPersistence(){
  shot("01-en-home");openRecipe();shot("02-recipe");a.buttons["favorite"].tap()
  let cart=a.buttons["add.shopping"];reveal(cart);cart.tap()
  let start=a.buttons["start.cooking"];a.swipeDown();a.swipeDown();reveal(start);start.tap()
  XCTAssertTrue(a.buttons["step.next"].waitForExistence(timeout:5));a.buttons["step.next"].tap();let step=a.staticTexts["step.text"].label;shot("03-cooking-step-two");a.buttons["close.cooking"].tap()
  a.terminate();a.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];a.launch();openRecipe();a.buttons["start.cooking"].tap();XCTAssertEqual(a.staticTexts["step.text"].label,step);a.buttons["close.cooking"].tap()
  a.navigationBars.buttons.element(boundBy:0).tap();t9("Shopping list").tap();XCTAssertTrue(a.buttons.matching(identifier:"shopping.flour").firstMatch.waitForExistence(timeout:5));a.buttons["shopping.flour"].tap();shot("04-shopping")
  t9("Baking plan").tap();a.buttons["plan.add"].tap();a.buttons["Vanilla cloud cupcakes"].tap();XCTAssertTrue(a.buttons["save.plan"].waitForExistence(timeout:5));a.buttons["save.plan"].tap();shot("05-planner");XCTAssertTrue(a.buttons["Send to Reminders"].waitForExistence(timeout:5))
  t9("Favorites").tap();shot("06-favorites");XCTAssertFalse(a.staticTexts["A place for your favorites"].exists)
 }
 func testTimerPauseResume(){openRecipe();let b=a.buttons["open.timer"];reveal(b);b.tap();a.switches["Notify me when ready"].tap();a.buttons["timer.start"].tap();let spring=XCUIApplication(bundleIdentifier:"com.apple.springboard");let deny=spring.buttons["Don’t Allow"].firstMatch;if deny.waitForExistence(timeout:5){deny.tap()}else if spring.buttons["Don't Allow"].firstMatch.exists{spring.buttons["Don't Allow"].firstMatch.tap()};if a.alerts.buttons["OK"].firstMatch.waitForExistence(timeout:3){a.alerts.buttons["OK"].firstMatch.tap()};a.navigationBars.buttons.element(boundBy:0).tap();a.swipeDown();a.swipeDown();a.swipeDown();reveal(a.buttons["timer.pause"]);XCTAssertTrue(a.buttons["timer.pause"].waitForExistence(timeout:5));a.buttons["timer.pause"].tap();XCTAssertTrue(a.buttons["Resume"].waitForExistence(timeout:5));shot("07-paused-timer");a.buttons["Resume"].tap();a.buttons["timer.cancel"].tap();XCTAssertFalse(a.buttons["timer.cancel"].exists)}
 func testFrenchAndGermanLaunch(){a.terminate();a.launchArguments=["-folio-reset","-AppleLanguages","(fr)","-AppleLocale","fr_FR"];a.launch();XCTAssertTrue(t9("Recettes").waitForExistence(timeout:10));shot("08-fr-home");a.terminate();a.launchArguments=["-AppleLanguages","(de)","-AppleLocale","de_DE"];a.launch();XCTAssertTrue(t9("Rezepte").waitForExistence(timeout:10));shot("09-de-home")}
 func testRemindersPermissionResponse(){t9("Baking plan").tap();a.buttons["plan.add"].tap();a.buttons["Vanilla cloud cupcakes"].tap();XCTAssertTrue(a.buttons["save.plan"].waitForExistence(timeout:5));a.buttons["save.plan"].tap();let export=a.buttons["Send to Reminders"];XCTAssertTrue(export.waitForExistence(timeout:5));export.tap();let spring=XCUIApplication(bundleIdentifier:"com.apple.springboard");let deny=spring.buttons["Don’t Allow"].firstMatch;if deny.waitForExistence(timeout:8){deny.tap()}else if spring.buttons["Don't Allow"].firstMatch.exists{spring.buttons["Don't Allow"].firstMatch.tap()};XCTAssertTrue(a.alerts.buttons["OK"].firstMatch.waitForExistence(timeout:8));shot("14-reminders-permission-response");a.alerts.buttons["OK"].firstMatch.tap();XCTAssertTrue(a.buttons["Send to Reminders"].waitForExistence(timeout:2) || a.buttons["Update reminder"].waitForExistence(timeout:2))}
 func testSearchAndPantry(){a.swipeDown();let search=a.searchFields.firstMatch;XCTAssertTrue(search.waitForExistence(timeout:5));search.tap();search.typeText("cocoa");XCTAssertTrue(a.buttons["recipe.brownie"].waitForExistence(timeout:5));shot("12-search");if a.buttons["Clear text"].firstMatch.exists{a.buttons["Clear text"].firstMatch.tap()};if a.navigationBars.buttons["Close"].firstMatch.exists{a.navigationBars.buttons["Close"].firstMatch.tap()}else{a.buttons["Cancel"].firstMatch.tap()};reveal(a.buttons["pantry.filter"]);a.buttons["pantry.filter"].tap();reveal(a.buttons["Dark chocolate"]);a.buttons["Dark chocolate"].tap();a.buttons["Done"].tap();XCTAssertTrue(a.buttons["recipe.brownie"].waitForExistence(timeout:5));XCTAssertFalse(a.buttons["recipe.cupcake"].exists);shot("13-pantry")}
 func testPortuguesePreferences(){a.terminate();a.launchArguments=["-folio-reset","-AppleLanguages","(pt-BR)","-AppleLocale","pt_BR"];a.launch();XCTAssertTrue(t9("Receitas").waitForExistence(timeout:10));shot("10-pt-home");a.buttons["settings"].tap();shot("11-pt-preferences");XCTAssertTrue(a.switches["Sincronizar notas, favoritos e planos"].exists)}
}
#else
import SwiftUI
import WidgetKit
@testable import FolioKitchen
final class V8Checks:XCTestCase {
 @MainActor func testWidgetFamilyRendersOffline(){
  let now=Date();let recipes=P4.all;let plans=Array(recipes.prefix(4).enumerated()).map{A6(id:String($0.offset),recipe:$0.element.id,date:now.addingTimeInterval(Double($0.offset+1)*86400),servings:$0.element.servings)}
  let snapshot=N4(timer:B2(recipe:recipes[0].id,began:now,end:now.addingTimeInterval(1200)),plan:plans,shopping:P4.shopping(["cupcake":6,"brownie":8],recipes));let e=R3(date:now,state:snapshot,recipe:recipes[0])
  for (family,w,h,name) in [(WidgetFamily.systemSmall,170.0,170.0,"small"),(.systemMedium,360.0,170.0,"medium"),(.systemLarge,360.0,390.0,"large"),(.accessoryRectangular,172.0,76.0,"lock-rect"),(.accessoryCircular,76.0,76.0,"lock-circle"),(.accessoryInline,220.0,32.0,"lock-inline")] {
   let renderer=ImageRenderer(content:D9(e:e,forced:family).padding(12).frame(width:w,height:h).background(p9paper));renderer.scale=2
   guard let image=renderer.uiImage else{XCTFail("Widget image missing: "+name);continue};XCTAssertGreaterThan(image.size.width,0);let attachment=XCTAttachment(image:image);attachment.name="widget-"+name;attachment.lifetime = .keepAlways;add(attachment)
  }
  let blank=ImageRenderer(content:D9(e:R3(date:now,state:.empty,recipe:recipes[0]),forced:.systemLarge).padding(12).frame(width:360,height:390).background(p9paper));XCTAssertNotNil(blank.uiImage)
 }
 func testBundledCookbookIsComplete(){let a=P4.all;XCTAssertEqual(a.count,12);XCTAssertEqual(Set(a.map(\.id)).count,a.count);for r in a{XCTAssertGreaterThanOrEqual(r.ingredients.count,3);XCTAssertGreaterThanOrEqual(r.steps.count,3);XCTAssertNotNil(UIImage(named:r.id));for l in ["en","de","fr","pt-BR"]{XCTAssertFalse((r.title[l] ?? "").isEmpty);XCTAssertFalse((r.allergens[l] ?? "").isEmpty);for s in r.steps{XCTAssertFalse((s.text[l] ?? "").isEmpty)}}}}
 func testScaledMethod(){let r=P4.all.first{$0.id=="cupcake"}!;XCTAssertTrue(r.step(0,12).contains("120"));XCTAssertFalse(r.step(0,12).contains("[[half]]"))}
 func testSharedIngredientAggregationAndScale(){let a=P4.shopping(["cupcake":6,"brownie":16],P4.all);XCTAssertEqual(a.first{$0.id=="flour"}?.amount,240);XCTAssertEqual(a.first{$0.id=="egg"}?.amount,5);XCTAssertEqual(a.filter{$0.id=="butter"}.count,1)}
 func testPantryUsesEveryIngredient(){let a=P4.filter(P4.all,"","all",["oats","honey"]);XCTAssertEqual(Set(a.map(\.id)),["cookie","berry"]);XCTAssertTrue(P4.filter(P4.all,"","all",["chocolate","apple"]).isEmpty)}
 func testTextAndCategory(){XCTAssertEqual(P4.filter(P4.all,"cocoa chocolate","all",[]).map(\.id),["brownie"]);XCTAssertEqual(P4.filter(P4.all,"","nobake",[]).map(\.id),["berry"])}
 func testSinglePortionLabel(){XCTAssertEqual(q4(1),"1 "+d8("portion"));XCTAssertEqual(q4(2),"2 "+d8("servings"))}
 func testCalendarWeekWindow(){let w=P4.w7();XCTAssertTrue(w.contains(w.lowerBound));XCTAssertFalse(w.contains(w.upperBound));XCTAssertEqual(Calendar.current.dateComponents([.day],from:w.lowerBound,to:w.upperBound).day,7)}
 func testMilkMeasuresAggregate(){let a=P4.shopping(["cupcake":6,"cookie":12],P4.all);XCTAssertEqual(a.filter{$0.id=="milk"}.count,1);XCTAssertEqual(a.first{$0.id=="milk"}?.amount,90)}
 func testDailyRollsOver(){let date=Date(timeIntervalSince1970:1760000000);XCTAssertNotEqual(P4.daily(date)?.id,P4.daily(date.addingTimeInterval(86400))?.id);XCTAssertEqual(P4.daily(date)?.id,P4.daily(date.addingTimeInterval(6*86400))?.id)}
 func testCloudMergeKeepsLatestAndTombstones(){let old=Date(timeIntervalSince1970:1),new=Date(timeIntervalSince1970:2);var a=J4();a.marks["a"]=E5(value:"1",date:old);a.notes["b"]=E5(value:"local",date:new);var b=J4();b.marks["a"]=E5(value:"0",date:new);b.notes["b"]=E5(value:"remote",date:old);b.plans["p"]=A6(id:"p",recipe:"apple",date:new,servings:4,removed:true,edited:new);a.merge(b);XCTAssertEqual(a.marks["a"]?.value,"0");XCTAssertEqual(a.notes["b"]?.value,"local");XCTAssertEqual(a.plans["p"]?.removed,true)}
 @MainActor func testSaveReloadAndStepBoundaries(){let u=FileManager.default.temporaryDirectory.appending(path:UUID().uuidString);defer{try? FileManager.default.removeItem(at:u)};let z=Z6(u);let r=z.recipes[0];z.star(r.id);z.note(r.id,"Less sweet next time");z.cart(r,12);for _ in 0..<20{z.next(r)};XCTAssertEqual(z.v.progress[r.id],r.steps.count);let fresh=Z6(u);XCTAssertTrue(fresh.favorite(r.id));XCTAssertEqual(fresh.v.cloud.notes[r.id]?.value,"Less sweet next time");XCTAssertEqual(fresh.v.cart[r.id],12);for _ in 0..<20{fresh.previous(r)};XCTAssertEqual(fresh.v.progress[r.id],0)}
 @MainActor func testTimerPauseResumeCancel() async {let u=FileManager.default.temporaryDirectory.appending(path:UUID().uuidString);defer{try? FileManager.default.removeItem(at:u)};let z=Z6(u);let r=z.recipes[0];await z.start(r,120,false);XCTAssertTrue(z.v.timer?.running==true);await z.pause();let held=z.v.timer?.held;XCTAssertNotNil(held);let fresh=Z6(u);XCTAssertEqual(fresh.v.timer?.held,held);await z.pause();XCTAssertNil(z.v.timer?.held);await z.start(z.recipes[1],60,false);XCTAssertEqual(z.v.timer?.recipe,r.id);await z.cancel();XCTAssertNil(z.v.timer)}
 @MainActor func testFuturePlansReachWidgetCache(){let u=FileManager.default.temporaryDirectory.appending(path:UUID().uuidString);defer{try? FileManager.default.removeItem(at:u)};let z=Z6(u);z.plan(z.recipes[0],Date().addingTimeInterval(10*86400),6);XCTAssertEqual(N4.read().plan.first?.recipe,z.recipes[0].id)}
 @MainActor func testPlanDeletionAndShopping(){let u=FileManager.default.temporaryDirectory.appending(path:UUID().uuidString);defer{try? FileManager.default.removeItem(at:u)};let z=Z6(u);z.plan(z.recipes[0],Date().addingTimeInterval(3600),6);z.plan(z.recipes[0],Date().addingTimeInterval(7200),6);z.plannerToCart();XCTAssertEqual(z.v.cart[z.recipes[0].id],12);let id=z.planned[0].id;z.removePlan(id);XCTAssertEqual(z.planned.count,1);XCTAssertTrue(z.v.cloud.plans[id]?.removed==true)}
}
#endif
